if(t.id==='podcast-waveform'||t.closest('#podcast-waveform')){let a=$('#podcast-audio'),wf=$('#podcast-waveform');if(a&&wf&&a.duration){let rect=wf.getBoundingClientRect();let pct=(e.clientX-rect.left)/rect.width;a.currentTime=pct*a.duration;updatePodcastUI()}}
