document.addEventListener('input',e=>{let t=e.target;if(t.id==='podcast-seek'){let a=$('#podcast-audio');if(a&&a.duration){a.currentTime=(+t.value/1000)*a.duration;updatePodcastUI()}}if(t.id==='collection-search')filterCollection();if(t.id==='library-search')filterLibrary();if(t.matches('[data-note]')){(state.notes[module.id]??=[])[+t.dataset.note]=t.value;save();$('#note-status').textContent='Draft saved on this device'}if(t.matches('[data-cap]')){state.capstone[t.dataset.cap]=t.value;delete state.capstone.review;save();if($('#capstone-review'))$('#capstone-review').innerHTML='<p>Your draft changed. Run the challenge again for an updated review.</p>'}});
document.addEventListener('change',e=>{let t=e.target;if(t.matches('[data-evidence]')){state.capstone.evidence=$$('[data-evidence]:checked').map(x=>x.dataset.evidence);delete state.capstone.review;save();$('#capstone-review').innerHTML='<p>Your evidence changed. Run the challenge again.</p>'}if(t.matches('[data-cap-check]')){state.capstone[t.dataset.capCheck]=t.checked;delete state.capstone.review;save();$('#capstone-review').innerHTML='<p>Your release boundary changed. Run the challenge again.</p>'}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#guide-panel').hidden)closeGuide();if(route==='media'&&!e.target.matches('input,textarea,select')){if(e.key==='ArrowLeft'){let infoVis=$('#media-infographics')?.getBoundingClientRect(),slideVis=$('#media-slides')?.getBoundingClientRect();let vH=window.innerHeight;if(infoVis&&infoVis.top<vH&&infoVis.bottom>0&&mediaInfoIdx>0){mediaInfoIdx--;updateInfoGraphic();e.preventDefault()}else if(slideVis&&slideVis.top<vH&&slideVis.bottom>0&&mediaSlideIdx>0){mediaSlideIdx--;updateSlide();e.preventDefault()}}if(e.key==='ArrowRight'){let infoVis=$('#media-infographics')?.getBoundingClientRect(),slideVis=$('#media-slides')?.getBoundingClientRect();let vH=window.innerHeight;if(infoVis&&infoVis.top<vH&&infoVis.bottom>0&&mediaInfoIdx<mediaInfographics.length-1){mediaInfoIdx++;updateInfoGraphic();e.preventDefault()}else if(slideVis&&slideVis.top<vH&&slideVis.bottom>0&&mediaSlideIdx<23){mediaSlideIdx++;updateSlide();e.preventDefault()}}}});
window.addEventListener('hashchange',render);
{let va=null,vb=$('#voice-intro');vb.addEventListener('click',()=>{if(va){va.pause();va.currentTime=0;va=null;vb.classList.remove('playing');vb.setAttribute('aria-label','Play voice introduction');return}va=new Audio('assets/voice-intro.mp3');vb.classList.add('playing');vb.setAttribute('aria-label','Stop voice introduction');va.play().catch(()=>{toast('Audio playback is unavailable.');vb.classList.remove('playing');va=null});va.addEventListener('ended',()=>{vb.classList.remove('playing');vb.setAttribute('aria-label','Play voice introduction');va=null})})}
